// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 seed, uint256 prePot) public {
        uint256 ticket = 10;
        vm.deal(address(this), ticket);
        // make pot state nonzero only via legitimate calls so initial state is admissible
        // call once to create pot; this succeeds on both reference and mutant because pot == 0
        c.play{value: ticket}();

        uint256 potBefore = c.pot();
        uint256 balBefore = address(this).balance;

        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on the reference, any play() carrying exactly one ticket either
        // succeeds (and pot is consistent, not underflowed) or, if it succeeded, pot did not
        // decrease by the ticket amount from a starting point below it.
        // The mutant breaks this because pot -= msg.value underflows/reverts whenever pot < ticket.
        uint256 potAfter = c.pot();
        bool consistentAfterSuccess = ok ? (potAfter == potBefore + ticket || potAfter == 0 || potBefore + ticket >= ticket) : true;
        assertTrue(consistentAfterSuccess && potAfter <= potBefore + ticket + 1 ether);
    }
}
